const raw = $input.first().json || {};

function tryParse(v) {
  if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return null; }
}

// Buscar SQL en TODOS los lugares posibles
let sql = raw.sql 
       || raw.query 
       || raw.input
       || raw.chatInput
       || raw.body?.sql 
       || raw.body?.query;

// Si lo que llegó es JSON string, parsear y buscar adentro
if (typeof sql === 'string' && (sql.trim().startsWith('{') || sql.trim().startsWith('['))) {
  const parsed = tryParse(sql);
  if (parsed && typeof parsed === 'object') {
    sql = parsed.sql || parsed.query || sql;
  }
}

sql = String(sql || '').trim();

// Limpiar prefijo 'sql\n' del chat
if (/^sql\s*\n/i.test(sql)) sql = sql.replace(/^sql\s*\n/i, '').trim();

// Quitar bloques markdown (```sql ... ```)
sql = sql.replace(/^```(?:sql)?\s*/i, '').replace(/```\s*$/, '').trim();

// Quitar comentarios SQL al inicio: líneas que empiezan con -- o bloques /* ... */
function stripLeadingComments(s) {
  let prev;
  do {
    prev = s;
    // Quitar comentarios de línea -- ... al inicio
    s = s.replace(/^\s*--[^\n]*\n?/, '');
    // Quitar comentarios de bloque /* ... */ al inicio
    s = s.replace(/^\s*\/\*[\s\S]*?\*\/\s*/, '');
    // Quitar líneas vacías al inicio
    s = s.replace(/^\s+/, '');
  } while (s !== prev);
  return s;
}
sql = stripLeadingComments(sql);

if (!sql) {
  throw new Error('sql vacío. Envía SELECT o WITH. Recibido: ' + JSON.stringify(raw).substring(0, 300));
}

const norm = sql.toUpperCase();
if (!norm.startsWith('SELECT') && !norm.startsWith('WITH')) {
  throw new Error('Solo SELECT o WITH. Recibido inicio: ' + norm.substring(0, 60));
}

// ── Decidir database ──
// DB 21 = prod-bia (raw HubSpot ETL, schemas: hubspot, hubspot_etl, dbo, cgm, hvt, google_drive, etc.)
// DB 2344 = prod-bia-gold (capa gold con schemas: operations, acquisition)
// Default: si la query menciona hubspot_etl/hubspot./dbo./cgm./hvt. → DB 21. Si menciona operations./acquisition. → DB 2344.
let database = Number(raw.database) || Number(raw.db) || Number(raw.body?.database) || 0;
if (!database) {
  const sqlLower = sql.toLowerCase();
  if (/\bhubspot_etl\.|\bhubspot\.|\bdbo\.|\bcgm\.|\bhvt\.|\bgoogle_drive\./.test(sqlLower)) {
    database = 21;
  } else {
    database = 2344; // default: gold layer
  }
}

return [{ json: { sql, database } }];

const resp = $input.first().json;
if (resp.error) return [{ json: { result: 'ERROR', error: resp.error, rows: [], count: 0 } }];
const cols = (resp.data?.cols || []).map(c => c.name);
const rows_raw = resp.data?.rows || [];
const rows = rows_raw.map(r => Object.fromEntries(cols.map((c, i) => [c, r[i]])));
return [{ json: { result: 'OK', rows, count: rows.length } }];
